card_css:
/* Variante 1: Minimalist Clean */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 1px solid rgba(0, 0, 0, 0.1);
  border-radius: 0.375rem;
  transition: all 0.3s ease-in-out;
}
.sl-card:hover {
  border-color: var(--sl-primary);
  box-shadow: 0 0.5rem 1.5rem rgba(0, 0, 0, 0.1);
  transform: translateY(-3px);
}

/* Variante 2: Organic Rounded */
.sl-card {
  background-color: var(--sl-card-bg);
  border: none;
  border-radius: 1.25rem;
  box-shadow: 0 0.4rem 1rem rgba(0, 0, 0, 0.08);
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
}
.sl-card:hover {
  box-shadow: 0 0.8rem 1.8rem rgba(0, 0, 0, 0.15), 0 0 0 3px var(--sl-primary); /* Primary color outline */
  transform: translateY(-6px) scale(1.01);
}

/* Variante 3: Earthy & Defined */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 1px solid rgba(0, 0, 0, 0.15);
  border-radius: 0.5rem;
  box-shadow: 0 0.2rem 0.4rem rgba(0, 0, 0, 0.08), inset 0 0 0 1px rgba(0,0,0,0.02);
  transition: all 0.3s ease;
}
.sl-card:hover {
  border-color: var(--sl-primary);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15), inset 0 0 0 2px var(--sl-primary); /* Inner glow with primary color */
  transform: translateY(-2px);
}

/* Variante 4: Modern Outlined */
.sl-card {
  background-color: var(--sl-card-bg);
  border: none;
  border-radius: 0.75rem;
  box-shadow: 0 0 0 1px rgba(0,0,0,0.05), 0 0.2rem 0.6rem rgba(0, 0, 0, 0.05);
  transition: all 0.3s ease-out;
}
.sl-card:hover {
  box-shadow: 0 0 0 2px var(--sl-primary), 0 0.5rem 1.2rem rgba(0, 0, 0, 0.1); /* Primary color outline and lift */
  transform: translateY(-4px);
}

/* Variante 5: Editorial Lined */
.sl-card {
  background-color: var(--sl-card-bg);
  border: none;
  border-top: 2px solid rgba(0, 0, 0, 0.1);
  border-bottom: 2px solid rgba(0, 0, 0, 0.1);
  border-radius: 0;
  box-shadow: 0 0.2rem 0.5rem rgba(0, 0, 0, 0.03);
  transition: all 0.3s ease-in-out;
}
.sl-card:hover {
  border-top-color: var(--sl-primary);
  border-bottom-color: var(--sl-primary);
  box-shadow: 0 0.4rem 0.8rem rgba(0, 0, 0, 0.08);
  transform: scale(1.005);
}

/* Variante Nova 1: Forest Depth (Soft Emboss) */
.sl-card {
  border: none;
  border-radius: 1.2rem;
  background-color: var(--sl-card-bg);
  box-shadow: 
    inset 4px 4px 8px rgba(0,0,0,0.05), 
    inset -4px -4px 8px rgba(255,255,255,0.7),
    6px 6px 12px rgba(0,0,0,0.1),
    -6px -6px 12px rgba(255,255,255,0.6);
  transition: all 0.3s ease;
}
.sl-card:hover {
  box-shadow: 
    inset 2px 2px 4px rgba(0,0,0,0.03), 
    inset -2px -2px 4px rgba(255,255,255,0.5),
    3px 3px 6px rgba(0,0,0,0.08),
    -3px -3px 6px rgba(255,255,255,0.4);
  transform: translateY(-2px); /* Subtle lift */
}

/* Variante Nova 2: Rustic Layer (Stacked Plank) */
.sl-card {
  border: 1px solid rgba(0,0,0,0.08);
  border-radius: 0.75rem;
  background-color: var(--sl-card-bg);
  box-shadow: 
    0 8px 0 -4px var(--sl-primary), /* Simulated plank beneath */
    0 8px 15px -4px rgba(0,0,0,0.15); /* General shadow */
  transition: all 0.3s ease;
}
.sl-card:hover {
  transform: translateY(-5px);
  box-shadow: 
    0 12px 0 -6px var(--sl-primary),
    0 12px 20px -6px rgba(0,0,0,0.25);
  border-color: rgba(0,0,0,0.12);
}

/* Variante Nova 3: Wildwood Carving (Deep Inset) */
.sl-card {
  border: 1px solid rgba(0,0,0,0.1);
  border-radius: 0.5rem;
  background-color: var(--sl-card-bg);
  box-shadow: 
    inset 0 0 15px rgba(0,0,0,0.25), /* Deep inset shadow */
    0 2px 5px rgba(0,0,0,0.1); /* Subtle overall lift */
  transition: all 0.3s ease;
}
.sl-card:hover {
  box-shadow: 
    inset 0 0 20px rgba(0,0,0,0.35),
    0 4px 8px rgba(0,0,0,0.15);
  transform: scale(1.01); /* Subtle "pop" */
}

/* Variante Nova 4: Glistening Dewdrop (Elevated & Polished) */
.sl-card {
  border: none;
  border-radius: 1.5rem;
  background-color: var(--sl-card-bg);
  box-shadow: 
    0 10px 30px rgba(0,0,0,0.1), /* Stronger elevation */
    inset 0 0 0 2px rgba(255,255,255,0.8); /* Inner sheen/highlight */
  transition: all 0.3s ease;
  overflow: hidden; /* Ensures no bleed on inner sheen */
}
.sl-card:hover {
  transform: translateY(-4px);
  box-shadow: 
    0 15px 40px rgba(0,0,0,0.15),
    inset 0 0 0 2px rgba(255,255,255,0.9);
}

/* Variante Nova 5: Canopy Shade (Accent Top) */
.sl-card {
  border: none;
  border-radius: 0.8rem;
  background-color: var(--sl-card-bg);
  box-shadow: 
    0 8px 15px rgba(0,0,0,0.3), /* Deep shadow below */
    inset 0 0 20px rgba(0,0,0,0.4); /* Darkens the "inside" */
  transition: all 0.3s ease;
  border-top: 6px solid var(--sl-primary); /* Strong primary accent */
}
.sl-card:hover {
  transform: translateY(-3px);
  box-shadow: 
    0 12px 20px rgba(0,0,0,0.4),
    inset 0 0 25px rgba(0,0,0,0.5);
  border-top-width: 8px; /* Accent becomes more prominent */
}
